using RabbitMQ.Client;
using RabbitMQ.Client.Events;
using System.Text;

//ALL OF IT GENERATED BY AI FOR TESTING A SKILL

// Read the broker connection string from the environment so credentials and
// deployment-specific connection details do not need to be stored in source.
string? brokerUri = Environment.GetEnvironmentVariable("RABBITMQ_URI");
if (string.IsNullOrWhiteSpace(brokerUri))
{
    throw new InvalidOperationException("Set the RABBITMQ_URI environment variable before starting the receiver.");
}

// Configure the RabbitMQ connection and give this client a recognizable name
// in broker management tools and connection logs.
var factory = new ConnectionFactory
{
    Uri = new Uri(brokerUri),
    ClientProvidedName = "RabbitMQ Receiver 2"
};

// Convert Ctrl+C into cancellation rather than terminating immediately. This
// lets the receiver stop consuming and release its broker resources normally.
using var cancellation = new CancellationTokenSource();
Console.CancelKeyPress += (_, eventArgs) =>
{
    eventArgs.Cancel = true;
    cancellation.Cancel();
};

// A connection represents the broker connection; a channel carries AMQP
// operations over it. Async disposal releases both when this program exits.
await using var connection = await factory.CreateConnectionAsync(cancellation.Token);
await using var channel = await connection.CreateChannelAsync(cancellationToken: cancellation.Token);

// These names match the companion sender's direct-exchange topology.
const string exchangeName = "test_exchange";
const string routingKey = "test_routing_key";
const string queueName = "test_queue";

// Declare the exchange and queue so they exist before consumption, then bind
// the queue to receive messages published with the matching routing key.
await channel.ExchangeDeclareAsync(exchangeName, ExchangeType.Direct, cancellationToken: cancellation.Token);
await channel.QueueDeclareAsync(queueName, durable: false, exclusive: false, autoDelete: false, cancellationToken: cancellation.Token);
await channel.QueueBindAsync(queueName, exchangeName, routingKey, cancellationToken: cancellation.Token);

// Limit this consumer to one unacknowledged delivery at a time. The broker
// will wait for an acknowledgement before sending the next message.
await channel.BasicQosAsync(0, 1, false, cancellation.Token);

// Handle deliveries asynchronously. Copy the broker-owned body before
// decoding it, print the UTF-8 text, and acknowledge only after handling it.
var consumer = new AsyncEventingBasicConsumer(channel);
consumer.ReceivedAsync += async (_, eventArgs) =>
{
    byte[] body = eventArgs.Body.ToArray();
    string message = Encoding.UTF8.GetString(body);

    Console.WriteLine($"Message received: {message}");
    await channel.BasicAckAsync(eventArgs.DeliveryTag, multiple: false);
};

// Disable automatic acknowledgements so each message is acknowledged by the
// callback only after it has been successfully processed.
string consumerTag = await channel.BasicConsumeAsync(queueName, autoAck: false, consumer);
Console.WriteLine($"Listening on queue '{queueName}'. Press Ctrl+C to stop.");

// Keep the top-level program alive while RabbitMQ dispatches deliveries to the
// callback. Cancellation is triggered by Ctrl+C.
try
{
    await Task.Delay(Timeout.Infinite, cancellation.Token);
}
catch (OperationCanceledException) when (cancellation.IsCancellationRequested)
{
    // Stop new deliveries for this consumer; the await-using declarations
    // dispose the channel and connection as the program exits.
    await channel.BasicCancelAsync(consumerTag);
}
